import { readFile, writeFile } from "node:fs/promises";

const path = new URL("../src/api/generated/schema.ts", import.meta.url);
const generated = await readFile(path, "utf8");
const header = `/**
 * 自动生成，请勿手工修改。
 * Generated by openapi-typescript from docs/api/openapi.json.
 */`;
const marked = generated.replace(
  /\/\*\*[\s\S]*?This file was auto-generated by openapi-typescript\.[\s\S]*?\*\//,
  header,
);
await writeFile(path, marked, "utf8");
